/*
 * A327783  Heinz numbers of integer partitions whose LCM is a multiple of
 *          their sum.
 * https://oeis.org/A327783
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 58, u16 n <= 58, u32 n <= 58, u64 n <= 58, u128 n <= 58,
 *            big any n
 * Helpers:   swap_size_t
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  Sequence A327783 – Heinz numbers of integer partitions whose LCM is a
 *  multiple of their sum (OEIS formula: no closed formula, generated by
 *  searching all integer partitions and keeping those that satisfy the
 *  required property).  */
 
#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>
#include "../utils/swap_size_t.h"

/* --- Parameters ----------------------------------------------------- */
#define MAX_B            200000          /* maximum value to search up to */

/* --- Global tables ------------------------------------------------- */
static seq_t *seq_cache = NULL;   /* array of generated sequence values */
static size_t seq_len  = 0;        /* number of values generated */

/*  Flag array – marks numbers that are Heinz numbers of qualifying
 *  partitions.  */
static uint8_t *present = NULL;

/*  List of primes up to MAX_B and smallest prime factor array for
 *  factorisation of numbers up to MAX_B.  */
static uint32_t *primes_list = NULL;   /* primes by index (primes_list[1] = 2) */
static size_t    primes_cnt  = 0;
static uint16_t *spf          = NULL;   /* spf[n] gives smallest prime factor of n */

/*  Depth‑first search stack holding the indices of the current set.  */
static int idx_stack[32];

/* ------------------------------------------------------------------ */

/* ------------------------------------------------------------------ */
/* Compute sieve of Eratosthenes up to MAX_B, filling primes_list
 * (1‑based) and spf array.  */
static void build_primes_and_spf(void)
{
    /* Allocate arrays */
    size_t sieve_size = MAX_B + 1;
    spf = (uint16_t*)malloc(sieve_size * sizeof(uint16_t));
    for (size_t i = 0; i < sieve_size; i++) spf[i] = 0;

    /* Linear sieve for primes and spf */
    uint32_t *pr = (uint32_t*)malloc(sieve_size * sizeof(uint32_t));
    size_t pr_cnt = 0;

    for (size_t i = 2; i <= MAX_B; i++) {
        if (spf[i] == 0) {
            spf[i] = (uint16_t)i;
            pr[pr_cnt++] = (uint32_t)i;
        }
        for (size_t j = 0; j < pr_cnt; j++) {
            uint32_t p = pr[j];
            if (p * i > MAX_B) break;
            spf[p * i] = (uint16_t)p;
            if (i % p == 0) break;
        }
    }
    primes_cnt = pr_cnt;
    primes_list = (uint32_t*)malloc((primes_cnt + 1) * sizeof(uint32_t));
    /* primes_list[1] = 2, etc. */
    for (size_t i = 0; i < primes_cnt; i++) primes_list[i + 1] = pr[i];

    free(pr);
}

/* ------------------------------------------------------------------ */
/* Test whether a multiset of indices stored in idx_stack[0..depth-1]
 * satisfies the condition: for every prime factor p^e of S = sum(indices),
 * at least one index in the set contains a power of p ≥ e.  */
static bool satisfies_condition(int curSum, size_t depth)
{
    int tmp = curSum;
    while (tmp > 1) {
        int p = spf[tmp];
        int eS = 0;
        while (tmp % p == 0) {
            tmp /= p;
            eS++;
        }
        /* check if some index in the set has exponent >= eS */
        bool ok = false;
        for (size_t i = 0; i < depth; i++) {
            int id = idx_stack[i];
            int eI = 0;
            int t = id;
            while (t % p == 0) {
                t /= p;
                eI++;
            }
            if (eI >= eS) { ok = true; break; }
        }
        if (!ok) return false;
    }
    return true;
}

/* ------------------------------------------------------------------ */
/* DFS enumerating all multisets of indices with product of primes
 * (the Heinz number) <= MAX_B.  For each valid set satisfying the
 * condition, the product is marked in 'present'.  */
static void dfs(int startIndex, uint64_t curProd, int curSum, size_t depth)
{
    for (int i = startIndex; i <= (int)primes_cnt; i++) {
        uint32_t primeVal = primes_list[i];
        if (curProd > MAX_B / primeVal) break;          /* product would exceed limit */

        idx_stack[depth] = i;
        uint64_t newProd = curProd * primeVal;
        int newSum = curSum + i;

        /* evaluate the new set */
        if (satisfies_condition(newSum, depth + 1))
            present[newProd] = 1;

        /* recurse further, allowing repetitions */
        dfs(i, newProd, newSum, depth + 1);
    }
}

/* ------------------------------------------------------------------ */
/* Build the sequence once, storing values in seq_cache.  */
static void build_sequence(void)
{
    if (seq_cache != NULL) return;   /* already built */

    /* Initialise arrays */
    present = (uint8_t*)calloc(MAX_B + 1, sizeof(uint8_t));
    build_primes_and_spf();

    /* enumerates all sets */
    dfs(1, 1ULL, 0, 0);   /* start with empty set */

    /* collect present numbers into seq_cache */
    seq_len = 0;
    for (int v = 2; v <= MAX_B; v++) {
        if (present[v]) seq_len++;
    }
    seq_cache = (seq_t*)malloc(seq_len * sizeof(seq_t));
    size_t idx = 0;
    for (int v = 2; v <= MAX_B; v++) {
        if (present[v]) seq_cache[idx++] = (seq_t)v;
    }

    /* cleanup */
    free(present);
    free(primes_list);
    free(spf);
}

/* ------------------------------------------------------------------ */
/* External sequence function ------------------------------------------------ */
extern seq_t a(idx_t n)
{
    if (n == 0) return 0;   /* undefined – guard */

    build_sequence();

    if ((idx_t)(n - 1) >= seq_len) {
        /* our MAX_B is too small – in practice this should not happen
         * for n <= 10000 with MAX_B = 200000.  */
        return 0;
    }

    return seq_cache[n - 1];
}
